{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "Pick units: click a bar, Shift-click to add one",
  "params": [
    {"name": "pick", "select": {"type": "point", "fields": ["unit_id"], "toggle": "event.shiftKey"}}
  ],
  "mark": {"type": "bar", "cursor": "pointer"},
  "encoding": {
    "x": {"field": "unit_id", "type": "ordinal"},
    "y": {"field": "value", "type": "quantitative"},
    "fillOpacity": {"condition": {"param": "pick", "value": 1}, "value": 0.3},
    "tooltip": [{"field": "unit_id"}, {"field": "name"}]
  }
}

import pandas as pd

# Three readings per unit, taken in rounds, units in a shuffled order:
# row 2 is unit 106's first reading, not unit 103's.
order = [104, 101, 106, 103, 102, 105]
rows = []
for t in (1, 2, 3):
    for unit_id in order:
        rows.append({"reading": f"{unit_id}-{t}", "unit_id": unit_id, "t": t, "level": unit_id % 7 + t})
return pd.DataFrame(rows)

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "Readings: red where the pool marks the picked units",
  "mark": {"type": "bar"},
  "encoding": {
    "x": {"field": "reading", "type": "ordinal", "sort": null},
    "y": {"field": "level", "type": "quantitative"},
    "color": {"condition": {"test": "datum.interacted === '1'", "value": "red"}, "value": "steelblue"},
    "tooltip": [{"field": "reading"}, {"field": "unit_id"}]
  }
}
